"use client";

import * as React from "react";

import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { EditPersonaDialog } from "@/components/mockups/voice-ownership/edit-persona-dialog";
import { PersonaList } from "@/components/mockups/voice-ownership/persona-list";
import { AppShell } from "@/components/shell/app-shell";
import { MockupShell } from "@/components/shell/mockup-shell";
import {
  EDITING_ID,
  PERSONAS,
  type Persona,
} from "@/lib/mockups/voice-ownership-data";

const ORG_VOICES = [
  { id: "some", label: "Has own voices" },
  { id: "none", label: "No own voices" },
] as const;

type OrgVoices = (typeof ORG_VOICES)[number]["id"];

export default function VoiceOwnershipPage() {
  const [orgVoices, setOrgVoices] = React.useState<OrgVoices>("some");
  const [editing, setEditing] = React.useState<Persona | null>(
    () => PERSONAS.find((persona) => persona.id === EDITING_ID) ?? null,
  );

  return (
    <MockupShell
      actions={
        <ToggleGroup
          aria-label="Organization voices"
          onValueChange={(next) => {
            if (next) setOrgVoices(next as OrgVoices);
          }}
          size="sm"
          type="single"
          value={orgVoices}
          variant="outline"
        >
          {ORG_VOICES.map((entry) => (
            <ToggleGroupItem key={entry.id} value={entry.id}>
              {entry.label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      }
      title="Global vs organization voices"
    >
      <AppShell active="Personas">
        <PersonaList onEdit={setEditing} />
      </AppShell>
      <EditPersonaDialog
        hasOrgVoices={orgVoices === "some"}
        onOpenChange={(open) => {
          if (!open) setEditing(null);
        }}
        persona={editing}
      />
    </MockupShell>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { LANGUAGE_NAMES } from "@/lib/design-system/data";

/** Must not wrap: a second line grows the row past the table's fixed 40px. */
export function LanguageChip({ languages }: { languages: string[] }) {
  return (
    <span className="flex flex-nowrap items-center gap-1 whitespace-nowrap">
      {languages.map((code) => (
        <Tooltip key={code}>
          <TooltipTrigger asChild>
            <Badge
              className="bg-muted text-muted-foreground"
              variant="secondary"
            >
              <span aria-label={LANGUAGE_NAMES[code]}>{code}</span>
            </Badge>
          </TooltipTrigger>
          <TooltipContent>{LANGUAGE_NAMES[code]}</TooltipContent>
        </Tooltip>
      ))}
    </span>
  );
}

export function NotApplicable() {
  return <span className="text-muted-foreground">—</span>;
}

"use client";

import * as React from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Field, FieldLabel } from "@/components/ui/field";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
  CloneVoiceIcon,
  CloseIcon,
  PreviewVoiceIcon,
  StopPreviewIcon,
} from "@/components/mockups/voice-ownership/icons";
import { OrbAvatar } from "@/components/shared/orb-avatar";
import {
  GENDERS,
  LANGUAGES,
  VOICES,
  type Gender,
  type Language,
  type Persona,
  type Voice,
} from "@/lib/mockups/voice-ownership-data";
import { cn } from "@/lib/utils";

/**
 * The platform's edit persona dialog (agents/components/agent-profile-form.tsx),
 * Identity and Voice sections. Behavior and pronunciation are unchanged by
 * DES-207 and left out.
 */
export function EditPersonaDialog({
  persona,
  hasOrgVoices,
  onOpenChange,
}: {
  persona: Persona | null;
  hasOrgVoices: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  return (
    <Dialog onOpenChange={onOpenChange} open={persona !== null}>
      <DialogContent
        // eslint-disable-next-line sarj/surface-width -- the shipped persona dialog is 800px; DES-207 changes only its Voice section
        className="sm:max-w-200"
        onOpenAutoFocus={(event) => event.preventDefault()}
        showCloseButton={false}
      >
        {persona ? (
          <PersonaForm
            hasOrgVoices={hasOrgVoices}
            key={persona.id}
            onClose={() => onOpenChange(false)}
            persona={persona}
          />
        ) : null}
      </DialogContent>
    </Dialog>
  );
}

function PersonaForm({
  persona,
  hasOrgVoices,
  onClose,
}: {
  persona: Persona;
  hasOrgVoices: boolean;
  onClose: () => void;
}) {
  const [language, setLanguage] = React.useState<Language>(persona.language);
  const [gender, setGender] = React.useState<Gender>(persona.gender);
  const [prompt, setPrompt] = React.useState(persona.prompt);
  const [voiceId, setVoiceId] = React.useState(persona.voiceId);

  return (
    <>
      <DialogHeader className="-mx-4 -mt-4 flex-row items-center justify-between gap-4 border-b px-6 py-5">
        <div className="flex items-center gap-3">
          <OrbAvatar name={persona.name} size="lg" />
          <div className="flex flex-col gap-0.5">
            <DialogTitle dir="auto">{persona.name}</DialogTitle>
            <DialogDescription>
              {language}
              {persona.isDefault ? " · Default" : null}
            </DialogDescription>
          </div>
        </div>
        <DialogClose asChild>
          <Button aria-label="Close" size="icon-sm" variant="ghost">
            <CloseIcon />
          </Button>
        </DialogClose>
      </DialogHeader>

      <ScrollArea className="-mx-4 -my-4 [&>[data-slot=scroll-area-viewport]]:max-h-150">
        <div className="flex flex-col gap-8 px-6 py-6">
          <section className="flex flex-col gap-4">
            <h3 className="text-base font-semibold">Identity</h3>
            <div className="grid grid-cols-2 gap-6">
              <Field>
                <FieldLabel htmlFor="persona-language">Language</FieldLabel>
                <Select
                  onValueChange={(value) => setLanguage(value as Language)}
                  value={language}
                >
                  <SelectTrigger className="w-full" id="persona-language">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent position="popper">
                    {LANGUAGES.map((option) => (
                      <SelectItem key={option} value={option}>
                        {option}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </Field>
              <Field>
                <FieldLabel htmlFor="persona-gender">Gender</FieldLabel>
                <Select
                  onValueChange={(value) => setGender(value as Gender)}
                  value={gender}
                >
                  <SelectTrigger className="w-full" id="persona-gender">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent position="popper">
                    {GENDERS.map((option) => (
                      <SelectItem key={option} value={option}>
                        {option}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </Field>
            </div>
            <Field>
              <FieldLabel htmlFor="persona-prompt">Persona prompt</FieldLabel>
              <Textarea
                className="min-h-32"
                dir="auto"
                id="persona-prompt"
                onChange={(event) => setPrompt(event.target.value)}
                rows={4}
                value={prompt}
              />
            </Field>
          </section>

          <VoiceSection
            gender={gender}
            hasOrgVoices={hasOrgVoices}
            language={language}
            onChange={setVoiceId}
            value={voiceId}
          />
        </div>
      </ScrollArea>

      <DialogFooter className="px-6">
        <DialogClose asChild>
          <Button variant="outline">Cancel</Button>
        </DialogClose>
        <Button onClick={onClose}>Save changes</Button>
      </DialogFooter>
    </>
  );
}

/** The organization's own voices first, then Sarj's short list — both filtered by the persona's language and gender. */
function VoiceSection({
  language,
  gender,
  hasOrgVoices,
  value,
  onChange,
}: {
  language: Language;
  gender: Gender;
  hasOrgVoices: boolean;
  value: string;
  onChange: (id: string) => void;
}) {
  const [playing, setPlaying] = React.useState<string | null>(null);

  React.useEffect(() => {
    if (!playing) return;
    const timer = window.setTimeout(() => setPlaying(null), 2400);
    return () => window.clearTimeout(timer);
  }, [playing]);

  const offered = VOICES.filter(
    (voice) => voice.language === language && voice.gender === gender,
  );
  const own = hasOrgVoices ? offered.filter((v) => v.owner === "org") : [];
  const sarj = offered.filter((v) => v.owner === "sarj");

  const card = (voice: Voice) => (
    <VoiceCard
      key={voice.id}
      onPreview={() => setPlaying(playing === voice.id ? null : voice.id)}
      playing={playing === voice.id}
      selected={voice.id === value}
      voice={voice}
    />
  );

  return (
    <section className="flex flex-col gap-4">
      <h3 className="text-base font-semibold">Voice</h3>
      <RadioGroup
        aria-label="Voice"
        className="flex flex-col gap-6"
        onValueChange={onChange}
        value={value}
      >
        <div className="flex flex-col gap-2">
          <span className="text-sm text-muted-foreground">
            Your organization
          </span>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
            {own.map(card)}
            {own.length === 0 ? <CloneTile /> : null}
          </div>
        </div>
        <div className="flex flex-col gap-2">
          <span className="text-sm text-muted-foreground">Sarj</span>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
            {sarj.map(card)}
          </div>
        </div>
      </RadioGroup>
    </section>
  );
}

/** The label stretches over the card; Preview sits above it so playing never selects. */
function VoiceCard({
  voice,
  selected,
  playing,
  onPreview,
}: {
  voice: Voice;
  selected: boolean;
  playing: boolean;
  onPreview: () => void;
}) {
  return (
    <Item
      className={cn(
        "relative cursor-pointer hover:bg-muted/50",
        selected && "border-primary ring-1 ring-primary",
      )}
      variant="outline"
    >
      <ItemMedia>
        <RadioGroupItem id={`voice-${voice.id}`} value={voice.id} />
      </ItemMedia>
      <ItemContent>
        <ItemTitle>
          <Label
            className="cursor-pointer after:absolute after:inset-0"
            htmlFor={`voice-${voice.id}`}
          >
            {voice.name}
          </Label>
        </ItemTitle>
        <ItemDescription>{voice.provider}</ItemDescription>
      </ItemContent>
      <ItemActions className="relative z-raised">
        <Button
          aria-label={`${playing ? "Stop" : "Play"} ${voice.name}`}
          onClick={onPreview}
          size="icon-sm"
          variant="ghost"
        >
          {playing ? <StopPreviewIcon /> : <PreviewVoiceIcon />}
        </Button>
      </ItemActions>
    </Item>
  );
}

/** Sits where the organization's first voice would, the same size as one; opens the DES-198 clone flow. */
function CloneTile() {
  return (
    <Item
      asChild
      className="border-dashed text-start hover:bg-muted/50"
      variant="outline"
    >
      <button type="button">
        <ItemMedia variant="icon">
          <CloneVoiceIcon />
        </ItemMedia>
        <ItemContent>
          <ItemTitle>Clone a voice</ItemTitle>
          <ItemDescription>Only your organization</ItemDescription>
        </ItemContent>
      </button>
    </Item>
  );
}

import {
  Cancel01Icon,
  Delete02Icon,
  Mic01Icon,
  PauseIcon,
  PencilEdit02Icon,
  PlayIcon,
  UserAdd01Icon,
} from "@hugeicons/core-free-icons";

import { icon } from "@/components/shared/icon";

export const PreviewVoiceIcon = icon(PlayIcon, "PreviewVoiceIcon");
export const StopPreviewIcon = icon(PauseIcon, "StopPreviewIcon");
export const CloneVoiceIcon = icon(Mic01Icon, "CloneVoiceIcon");
export const EditPersonaIcon = icon(PencilEdit02Icon, "EditPersonaIcon");
export const DeletePersonaIcon = icon(Delete02Icon, "DeletePersonaIcon");
export const NewPersonaIcon = icon(UserAdd01Icon, "NewPersonaIcon");
export const CloseIcon = icon(Cancel01Icon, "CloseIcon");

"use client";

import * as React from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { TooltipProvider } from "@/components/ui/tooltip";
import { LanguageChip } from "@/components/design-system/call-table";
import {
  DeletePersonaIcon,
  EditPersonaIcon,
  NewPersonaIcon,
} from "@/components/mockups/voice-ownership/icons";
import {
  DataTable,
  DataTableHead,
  DataTableHeaderRow,
} from "@/components/shared/data-table";
import { ChoiceFilter, FilterBar } from "@/components/shared/filter-bar";
import { ListFooter } from "@/components/shared/list-footer";
import { PageHeader } from "@/components/shared/page-header";
import {
  LANGUAGE_CODES,
  LANGUAGES,
  PERSONAS,
  voiceById,
  type Persona,
} from "@/lib/mockups/voice-ownership-data";

/**
 * The platform's persona list (app/agents) as it ships, plus one column:
 * Voice, with who owns it — so two personas on one voice are visible.
 */
export function PersonaList({
  onEdit,
}: {
  onEdit: (persona: Persona) => void;
}) {
  const [language, setLanguage] = React.useState<string | null>(null);
  const rows = PERSONAS.filter(
    (persona) => !language || persona.language === language,
  );

  return (
    <TooltipProvider>
      <main className="flex w-full flex-col gap-4 p-8">
        <PageHeader title="Personas" />
        <div className="flex flex-wrap items-center justify-between gap-2">
          <FilterBar activeCount={language ? 1 : 0}>
            <ChoiceFilter
              field="Language"
              onChange={setLanguage}
              options={LANGUAGES.map((entry) => ({
                value: entry,
                label: entry,
              }))}
              value={language}
            />
          </FilterBar>
          <Button>
            <NewPersonaIcon />
            New persona
          </Button>
        </div>

        <DataTable>
          <TableHeader>
            <DataTableHeaderRow>
              <DataTableHead>Name</DataTableHead>
              <DataTableHead>Language</DataTableHead>
              <DataTableHead>Gender</DataTableHead>
              <DataTableHead>Voice</DataTableHead>
              <DataTableHead>Created</DataTableHead>
              <DataTableHead className="text-end">
                <span className="sr-only">Actions</span>
              </DataTableHead>
            </DataTableHeaderRow>
          </TableHeader>
          <TableBody>
            {rows.map((persona) => {
              const voice = voiceById(persona.voiceId);
              return (
                <TableRow key={persona.id}>
                  <TableCell>
                    <span className="flex items-center gap-2">
                      <bdi className="font-medium">{persona.name}</bdi>
                      {persona.isDefault ? (
                        <Badge
                          className="bg-primary-tint text-primary-tint-foreground"
                          variant="secondary"
                        >
                          Default
                        </Badge>
                      ) : null}
                    </span>
                  </TableCell>
                  <TableCell>
                    <LanguageChip
                      languages={[LANGUAGE_CODES[persona.language]]}
                    />
                  </TableCell>
                  <TableCell className="text-muted-foreground">
                    {persona.gender}
                  </TableCell>
                  <TableCell>
                    {voice ? (
                      // A Sarj voice is the norm, so only the organization's own is marked.
                      <span className="flex items-center gap-2">
                        {voice.name}
                        {voice.owner === "org" ? (
                          <Badge variant="secondary">Your org</Badge>
                        ) : null}
                      </span>
                    ) : null}
                  </TableCell>
                  <TableCell className="text-muted-foreground tabular-nums">
                    {persona.createdAt}
                  </TableCell>
                  <TableCell className="text-end">
                    <span className="flex items-center justify-end gap-1">
                      {persona.isDefault ? null : (
                        <Button size="sm" variant="outline">
                          Set as default
                        </Button>
                      )}
                      <Button
                        aria-label={`Edit persona ${persona.name}`}
                        onClick={() => onEdit(persona)}
                        size="icon-sm"
                        variant="ghost"
                      >
                        <EditPersonaIcon />
                      </Button>
                      <Button
                        aria-label={`Delete persona ${persona.name}`}
                        disabled={persona.isDefault}
                        size="icon-sm"
                        variant="ghost"
                      >
                        <DeletePersonaIcon />
                      </Button>
                    </span>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </DataTable>

        <ListFooter
          atEnd
          from={1}
          noun="personas"
          pageSize={25}
          shown={rows.length}
          total={rows.length}
        />
      </main>
    </TooltipProvider>
  );
}

import * as React from "react";

import { Table, TableHead, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";

export function DataTable({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      <Table className={cn("[&_td]:h-10 [&_td]:px-4 [&_th]:px-4", className)}>
        {children}
      </Table>
    </div>
  );
}

export function DataTableHeaderRow({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <TableRow className="bg-muted/50 hover:bg-muted/50">{children}</TableRow>
  );
}

export function DataTableHead({
  className,
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <TableHead className={cn("font-semibold text-foreground", className)}>
      {children}
    </TableHead>
  );
}

"use client";

import * as React from "react";
import { Cancel01Icon, PlusSignIcon } from "@hugeicons/core-free-icons";
import type { DateRange } from "react-day-picker";

import { Button } from "@/components/ui/button";
import { ButtonGroup } from "@/components/ui/button-group";
import { Calendar } from "@/components/ui/calendar";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Field, FieldLabel } from "@/components/ui/field";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Separator } from "@/components/ui/separator";
import { icon } from "@/components/shared/icon";

const AddIcon = icon(PlusSignIcon, "AddIcon");
const ClearIcon = icon(Cancel01Icon, "ClearIcon");

export type { DateRange };
type FilterOption = { value: string; label: string };
export type Range = { min?: number; max?: number };

export function FilterBar({
  children,
  activeCount = 0,
  onClearAll,
}: {
  children: React.ReactNode;
  /** How many filters are set. Clear all appears at two. */
  activeCount?: number;
  onClearAll?: () => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      {children}
      {activeCount >= 2 ? (
        <Button variant="ghost" size="xs" onClick={onClearAll}>
          Clear all
        </Button>
      ) : null}
    </div>
  );
}

/** One tree for both states: swapping the trigger once a value is set would remount it and close the open list. */
function Chip({
  field,
  summary,
  onClear,
  trigger,
}: {
  field: string;
  summary: string | null;
  onClear: () => void;
  trigger: (button: React.ReactElement) => React.ReactNode;
}) {
  return (
    <ButtonGroup>
      {trigger(
        <Button variant="outline" size="xs">
          {summary ? (
            <>
              {field}: <span className="font-semibold">{summary}</span>
            </>
          ) : (
            <>
              <AddIcon />
              {field}
            </>
          )}
        </Button>,
      )}
      {summary ? (
        <Button
          variant="outline"
          size="icon-xs"
          aria-label={`Clear ${field}`}
          onClick={onClear}
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  );
}

function manySummary(options: FilterOption[], value: string[]) {
  if (!value.length) return null;
  const labels = value.map(
    (item) => options.find((option) => option.value === item)?.label ?? item,
  );
  if (labels.length === 1) return labels[0];
  if (labels.length === 2 && labels.join(", ").length <= 24)
    return labels.join(", ");
  return `${labels[0]} +${labels.length - 1}`;
}

const DAY = 24 * 60 * 60 * 1000;

function datePresets(today: Date) {
  return [
    { label: "Today", from: today },
    { label: "Last 7 days", from: new Date(today.getTime() - 6 * DAY) },
    { label: "Last 30 days", from: new Date(today.getTime() - 29 * DAY) },
  ];
}

function dateSummary(value: DateRange | undefined, today: Date) {
  if (!value?.from) return null;
  const preset = datePresets(today).find(
    (entry) =>
      value.from?.toDateString() === entry.from.toDateString() &&
      value.to?.toDateString() === today.toDateString(),
  );
  return (
    preset?.label ??
    [value.from, value.to]
      .filter(Boolean)
      .map((date) =>
        date!.toLocaleDateString("en-GB", { day: "numeric", month: "short" }),
      )
      .join(" – ")
  );
}

function rangeSummary(range: Range | null, unit: string) {
  if (!range) return null;
  const { min, max } = range;
  if (min !== undefined && max !== undefined) return `${min}–${max} ${unit}`;
  if (min !== undefined) return `Over ${min} ${unit}`;
  if (max !== undefined) return `Under ${max} ${unit}`;
  return null;
}

/** Past this many options the list gets a search box. */
const SEARCH_FROM = 8;

function OptionList({
  button,
  field,
  options,
  selected,
  onSelect,
  onClear,
  closeOnSelect,
}: {
  button: React.ReactElement;
  field: string;
  options: FilterOption[];
  selected: string[];
  onSelect: (value: string) => void;
  onClear?: () => void;
  closeOnSelect: boolean;
}) {
  const [open, setOpen] = React.useState(false);
  // Ticked ones float to the top only when the list opens, not under the pointer.
  const [order, setOrder] = React.useState(options);

  if (options.length < SEARCH_FROM) {
    return (
      <DropdownMenu modal={false} open={open} onOpenChange={setOpen}>
        <DropdownMenuTrigger asChild>{button}</DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          className="w-auto min-w-(--radix-dropdown-menu-trigger-width)"
        >
          {options.map((option) => (
            <DropdownMenuCheckboxItem
              checked={selected.includes(option.value)}
              key={option.value}
              onSelect={(event) => {
                if (!closeOnSelect) event.preventDefault();
                onSelect(option.value);
              }}
            >
              {option.label}
            </DropdownMenuCheckboxItem>
          ))}
          {onClear && selected.length ? (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onSelect={onClear}>Clear</DropdownMenuItem>
            </>
          ) : null}
        </DropdownMenuContent>
      </DropdownMenu>
    );
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && options.length >= SEARCH_FROM)
          setOrder([
            ...options.filter((o) => selected.includes(o.value)),
            ...options.filter((o) => !selected.includes(o.value)),
          ]);
        setOpen(next);
      }}
    >
      <PopoverTrigger asChild>{button}</PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          {options.length >= SEARCH_FROM ? (
            <CommandInput placeholder={`Search ${field.toLowerCase()}`} />
          ) : null}
          <CommandList>
            <CommandEmpty>No match</CommandEmpty>
            <CommandGroup>
              {(options.length >= SEARCH_FROM ? order : options).map(
                (option) => (
                  <CommandItem
                    className="truncate"
                    data-checked={selected.includes(option.value)}
                    key={option.value}
                    onSelect={() => {
                      onSelect(option.value);
                      if (closeOnSelect) setOpen(false);
                    }}
                    value={option.label}
                  >
                    {option.label}
                  </CommandItem>
                ),
              )}
            </CommandGroup>
          </CommandList>
          {onClear && selected.length ? (
            <div className="border-t p-1">
              <Button
                className="w-full"
                onClick={onClear}
                size="sm"
                variant="ghost"
              >
                Clear
              </Button>
            </div>
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export function SelectFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string;
  options: FilterOption[];
  value: string[];
  onChange: (value: string[]) => void;
}) {
  return (
    <Chip
      field={field}
      summary={manySummary(options, value)}
      onClear={() => onChange([])}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect={false}
          field={field}
          onClear={() => onChange([])}
          onSelect={(item) =>
            onChange(
              value.includes(item)
                ? value.filter((entry) => entry !== item)
                : [...value, item],
            )
          }
          options={options}
          selected={value}
        />
      )}
    />
  );
}

export function ChoiceFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string;
  options: FilterOption[];
  value: string | null;
  onChange: (value: string | null) => void;
}) {
  return (
    <Chip
      field={field}
      summary={options.find((option) => option.value === value)?.label ?? null}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect
          field={field}
          onSelect={(item) => onChange(item === value ? null : item)}
          options={options}
          selected={value ? [value] : []}
        />
      )}
    />
  );
}

